[standards/infrastructure/hosting/STD-INFRA-HST-001-web-frontend-hosting.md#nginx-configuration-requirements]

#### nginx Configuration Requirements

```nginx
# nginx.conf for SPA hosting from S3 via init container pattern
server {
    listen 8080;
    server_name _;

    root /usr/share/nginx/html;
    index index.html;

    # Security response headers (mirrors CloudFront response headers policy)
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    # Replace with a project-appropriate Content-Security-Policy value.
    # Do NOT use 'unsafe-inline' — prohibited by REQ-HST-001e without a
    # documented compensating control (nonce or hash) approved by Security.
    # If your framework requires 'unsafe-inline' for styles (e.g., CSS-in-JS),
    # use a nonce injected via nginx sub_filter or an upstream proxy instead.
    add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'" always;

    # SPA routing: serve index.html for all paths that do not match a file
    location / {
        try_files $uri $uri/ /index.html;
    }
}
```
